"""Call transcripts for search and analytics: real calls from SQL plus synthetic ones generated by replaying the golden scenarios.

Synthetic calls are generated, not collected: scenario scripts are sampled, sometimes corrupted (noise, a swapped line, an early
hang-up) and played through the real brain, so outcomes, intents and traces are genuine but the volume is made up. They exist to
exercise the aggregation pipeline and are labelled `source: synthetic` everywhere.
"""

from __future__ import annotations

import random
from collections import Counter
from math import log
from pathlib import Path
from typing import Any

from sqlalchemy import select
from sqlalchemy.orm import Session

from app import models as m
from app.brain.dialog import Brain
from app.brain.retrieval import FaqIndex
from app.brain.state import DialogState
from app.config import Settings
from app.db import Database
from app.knowledge.search import tokenize
from app.models import Base
from app.rules import ClinicRules
from app.scenarios import PINNED_NOW, load_scenarios
from app.seed import seed_demo
from app.services.clinic import ClinicService
from app.services.engagement import LogNotifier, Outbox, WaitlistService

NOISE = [
    "uhh",
    "asdf",
    "hmm what",
    "...",
    "blah blah",
    "umm I forgot",
    "کچھ سمجھ نہیں آ رہا",
    "ہوں ہوں",
    "what was I saying",
]


def _call_doc(
    call_id: str, source: str, lang: str, turns: list[dict[str, str]], st: DialogState, intents: list[str]
) -> dict[str, Any]:
    user = [t["text"] for t in turns if t["role"] == "user" and t["text"]]
    return {
        "call_id": call_id,
        "source": source,
        "lang": lang,
        "outcome": st.outcome(),
        "end_reason": st.end_reason or "none",
        "ended": st.ended,
        "turns": len([t for t in turns if t["role"] == "user"]),
        "intents": sorted(set(intents)),
        "user_text": " \n ".join(user),
        "last_user_text": user[-1] if user else "",
        "transcript": "\n".join(f"{'Caller' if t['role'] == 'user' else 'Assistant'}: {t['text']}" for t in turns),
    }


def _play(rules: ClinicRules, lines: list[str], lang: str) -> tuple[list[dict[str, str]], DialogState, list[str]]:
    db = Database(Settings(app_env="test", database_url="sqlite:///:memory:", bcrypt_rounds=4))
    Base.metadata.create_all(db.engine)
    with db.session() as session:
        svc = ClinicService(session, rules, now_fn=lambda: PINNED_NOW)
        svc.sync_providers()
        seed_demo(svc, PINNED_NOW)
        svc.waitlist = WaitlistService(svc, Outbox(session, LogNotifier()))
        svc.on_freed = svc.waitlist.on_slot_freed
        brain = Brain(svc, FaqIndex(rules.faq), "synthetic")
        st = DialogState(lang=lang, lang_locked=True)
        turns = [{"role": "assistant", "text": brain.start(st).reply}]
        intents: list[str] = []
        for line in lines:
            if st.ended:
                break
            r = brain.handle(st, line)
            turns += [{"role": "user", "text": line}, {"role": "assistant", "text": r.reply}]
            if r.trace.get("intent"):
                intents.append(r.trace["intent"]["name"])
        return turns, st, intents


def synthetic_calls(
    rules: ClinicRules, n: int = 300, seed: int = 7, scenarios_dir: str | Path = "scenarios"
) -> list[dict[str, Any]]:
    rng = random.Random(seed)
    scenarios = load_scenarios(scenarios_dir)
    bank = [(step["say"], s.get("lang", "en")) for s in scenarios for step in s["steps"] if step["say"].strip()]
    calls: list[dict[str, Any]] = []
    for i in range(n):
        sc = rng.choice(scenarios)
        lang = sc.get("lang", "en")
        lines = [step["say"] for step in sc["steps"]]
        roll = rng.random()
        if roll < 0.30:  # a line the caller garbled
            lines[rng.randrange(len(lines))] = rng.choice(NOISE)
        elif roll < 0.45:  # replaced by something unrelated from another call
            lines[rng.randrange(len(lines))] = rng.choice([b[0] for b in bank if b[1] == lang] or [NOISE[0]])
        elif roll < 0.55 and len(lines) > 1:  # hung up early
            lines = lines[: rng.randrange(1, len(lines))]
        elif roll < 0.62:  # kept saying things the assistant could not follow
            lines += [rng.choice(NOISE) for _ in range(3)]
        turns, st, intents = _play(rules, lines, lang)
        calls.append(_call_doc(f"syn-{seed}-{i:04d}", "synthetic", lang, turns, st, intents))
    return calls


def calls_from_sql(db: Session) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for call in db.scalars(select(m.CallSession).order_by(m.CallSession.started_at)):
        st = DialogState.from_json(call.state_json)
        turns: list[dict[str, str]] = []
        intents: list[str] = []
        for t in sorted(call.turns, key=lambda x: x.idx):
            if t.user_text:
                turns.append({"role": "user", "text": t.user_text})
            turns.append({"role": "assistant", "text": t.reply_text})
        out.append(_call_doc(call.id, "real", st.lang, turns, st, intents))
    return out


def insights_in_python(calls: list[dict[str, Any]], outcome: str = "handoff", top: int = 10) -> dict[str, Any]:
    """The same aggregation Elasticsearch does, in plain Python: the fallback, and the oracle for tests."""
    hit = [c for c in calls if c["outcome"] == outcome]
    last = Counter(c["last_user_text"] for c in hit if c["last_user_text"])
    in_c = Counter(t for c in hit for t in set(tokenize(c["user_text"])))
    all_c = Counter(t for c in calls for t in set(tokenize(c["user_text"])))
    n_hit, n_all = max(len(hit), 1), max(len(calls), 1)
    terms = [
        {"term": t, "count": c, "score": round((c / n_hit) / (all_c[t] / n_all) * log(1 + c), 3)}
        for t, c in in_c.items()
        if c >= 2
    ]
    terms.sort(key=lambda x: (-x["score"], x["term"]))
    return {
        "outcome": outcome,
        "calls": len(hit),
        "of_total": len(calls),
        "top_last_utterances": [{"text": t, "count": c} for t, c in last.most_common(top)],
        "signal_terms": terms[:top],
        "backend": "python",
    }


class CallIndex:
    """Elasticsearch index of transcripts: full-text search over what callers said, and aggregations over how calls ended."""

    def __init__(self, es: Any, prefix: str = "clinic"):
        self.es, self.index = es, f"{prefix}_calls"

    def ensure_index(self, recreate: bool = False) -> None:
        if recreate and self.es.indices.exists(index=self.index):
            self.es.indices.delete(index=self.index)
        if not self.es.indices.exists(index=self.index):
            self.es.indices.create(
                index=self.index,
                mappings={
                    "properties": {
                        "call_id": {"type": "keyword"},
                        "source": {"type": "keyword"},
                        "lang": {"type": "keyword"},
                        "outcome": {"type": "keyword"},
                        "end_reason": {"type": "keyword"},
                        "ended": {"type": "boolean"},
                        "turns": {"type": "integer"},
                        "intents": {"type": "keyword"},
                        "user_text": {"type": "text"},
                        "last_user_text": {"type": "text", "fields": {"raw": {"type": "keyword", "ignore_above": 256}}},
                        "transcript": {"type": "text", "index": False},
                    }
                },
            )

    def index_calls(self, calls: list[dict[str, Any]]) -> int:
        from elasticsearch import helpers

        self.ensure_index()
        ok, _ = helpers.bulk(
            self.es, [{"_index": self.index, "_id": c["call_id"], "_source": c} for c in calls], refresh="wait_for"
        )
        return int(ok)

    def search(self, q: str, outcome: str | None = None, size: int = 10) -> list[dict[str, Any]]:
        must: list[dict[str, Any]] = [{"match": {"user_text": q}}] if q else [{"match_all": {}}]
        flt = [{"term": {"outcome": outcome}}] if outcome else []
        res = self.es.search(index=self.index, query={"bool": {"must": must, "filter": flt}}, size=size)
        return [{**h["_source"], "score": h["_score"]} for h in res["hits"]["hits"]]

    def insights(self, outcome: str = "handoff", top: int = 10) -> dict[str, Any]:
        res = self.es.search(
            index=self.index,
            size=0,
            query={"term": {"outcome": outcome}},
            aggs={
                "last": {"terms": {"field": "last_user_text.raw", "size": top}},
                "signal": {"significant_text": {"field": "user_text", "size": top, "min_doc_count": 2}},
            },
        )
        total = self.es.count(index=self.index)["count"]
        return {
            "outcome": outcome,
            "calls": res["hits"]["total"]["value"],
            "of_total": total,
            "top_last_utterances": [
                {"text": b["key"], "count": b["doc_count"]} for b in res["aggregations"]["last"]["buckets"]
            ],
            "signal_terms": [
                {"term": b["key"], "count": b["doc_count"], "score": round(b["score"], 3)}
                for b in res["aggregations"]["signal"]["buckets"]
            ],
            "backend": "elasticsearch",
        }

    def count(self) -> int:
        return int(self.es.count(index=self.index)["count"]) if self.es.indices.exists(index=self.index) else 0
